/**
 * For search
 */
let __type_search_timeout = null;

document.addEventListener("DOMContentLoaded", async () => {
  let images = document.querySelectorAll("img");
  let overlay_loading = document.querySelector("overlay[loading-app]");

  /**
   * KEYBOARD SHORTCUT
   */
  document.addEventListener("keyup", (e) => {
    if (!e.key) return;

    /**
     * ? T
     *
     * Test things.
     */
    if (e.key.toLowerCase() === "t") {
      return;
    }

    /**
     * ? ESC
     */
    if (e.key.toLowerCase() === "escape") {
      /**
       * Close ui compose elements
       */
      let reactions = document.find("[reactions-window]");
      let composer = document.find("[composer]");
      if (composer || reactions) Frontend.close_composer();
    }

    /**
     * ? E
     *
     * Begin the editor mode.
     */
    // if (e.key.toLowerCase() === "e") {
    //   if (!__current_user.id) return;

    //   Page.get(`/editor`);
    // }

    /**
     * ? P
     *
     * Go to profile.
     */
    // if (e.key.toLowerCase() === "p") {
    //   if (!__current_user.id) return;

    //   Page.get(`/u/${__current_user.id}`);
    // }
  });

  /**
   * Close all compose ui elements on scroll.
   */
  $(window).on("scroll", function (e) {
    Frontend.close_composer();
  });

  /**
   * Initialize the application.
   */
  await init_application(overlay_loading, images, Setting.INIT_TIMEOUT);

  /**
   * Generalize click event listeners
   */
  document.addEventListener("click", async function (e) {
    let anchor = e.target.closest("a");
    let href;

    /**
     * Close jump menu
     */
    // if (jumper)
    //   jumper.unactivate();

    if (anchor !== null) {
      href = anchor.getAttribute("href");

      if (!anchor.hasAttribute("extern") && href) {
        e.preventDefault();

        await Page.get(href, false, anchor);
      }
    }

    /**
     * Play beatmap audios
     */
    let beatmapset_play = e.target.closest('[data-action="beatmap:set,play"]');
    if (beatmapset_play) Audio.start(beatmapset_play.dataset.setId);

    /**
     * Close notification center
     */
    let notification_center = document.find("[notifications]");
    let notifications = e.target.closest("[notifications]");
    if (
      notification_center &&
      (!notifications || !notifications.matches("[notifications]"))
    )
      Frontend.close_notifications();

    /**
     * Close user menu on outside click.
     */
    let user_menu = e.target.closest("user-menu");
    if (!user_menu || !user_menu.matches("user-menu"))
      Frontend.close_user_menu();

    /**
     * Close mode menu on outside click.
     */
    let mode_menu = e.target.closest("mode-menu");
    if (!mode_menu || !mode_menu.matches("mode-menu"))
      Frontend.close_mode_menu();
  });

  /**
   * Generalize keypress events
   */
  document.addEventListener("keypress", function (e) {
    if (!e.key) return;

    if (e.key.toLowerCase() === "enter") e.preventDefault();
    if (
      e.key.toLowerCase() === "enter" &&
      (e.target.tagName.toLowerCase() === "input" ||
        e.target.tagName.toLowerCase() === "textarea") &&
      e.target.hasAttribute("enter-submitable")
    ) {
      e.preventDefault();

      let form = e.target.closest("form");
      let button = form.querySelector("[submit-closest]");
      if (form && button && !button.hasAttribute("disabled")) button.click();
    }
  });

  /**
   * Generalite scroll event
   */
  document.addEventListener("scroll", (e) => {
    let $scroll_container = document.body.querySelectorAll(
      "[scroll-manipulated]"
    );

    if (!$scroll_container[0]) return;

    if (
      document.documentElement.scrollTop >= 40 ||
      document.body.scrollTop >= 40
    ) {
      $scroll_container.forEach((s) => {
        s.setAttribute("scrolled", true);
      });
    } else {
      $scroll_container.forEach((s) => {
        s.setAttribute("scrolled", false);
      });
    }
  });

  /**
   * Popstate event (going back in history)
   */
  window.addEventListener("popstate", async (e) => {
    if (!e.state) return;

    Frontend.close_overlays();

    if (e.state.href == undefined || !e.state.href) return;

    await Page.get(e.state.href, true);
  });
});

/**
 * Initialize the application
 */
const init_application = async (overlay, images, sleeper) => {
  /**
   * If the policies are not yet accepted, return the user to the
   * consent page.
   */
  if (Page.load_policies_consent_page()) return;

  /** Load all inline images */
  console.log(
    "%cIn case you wonder, why I load every image separately using JavaScript, try to take a deeper look at the overall appearance and animated behaviour of this project. Instead of each image building up frame by frame, they fade in on complete load up for a clean and nice look. It's the small things that make it a great project.",
    "color:grey;"
  );

  /** Get the current page */
  await Page.get(window.location.pathname + window.location.search, true);

  /** Close the init overlay */
  Frontend.close_overlays();

  /** Set body to initialized */
  document.body.setAttribute("initialized", true);

  console.log(
    "%c🌞 Framework/Bruder loaded!",
    "color:light-blue;font-size:1.32em;font-weight:800;",
    "\nheia.kim ©️ 2022-" + new Date().getFullYear()
  );

  /**
   * Find cookie notice and show, if available
   */
  let menu_option = document.body.querySelector("[cookie-notice]");
  let menu_option_actives;

  /**
   * Show feedback notice if available.
   */
  if (!menu_option) {
    Frontend.show_header_notice(document.querySelector("[feedback-notice]"));

    return;
  }

  menu_option_actives = menu_option.querySelectorAll("[active=false]");

  menu_option.removeAttribute("donotshow");
  setTimeout(() => {
    menu_option_actives.forEach((a) => {
      a.setAttribute("active", true);
    });
  }, 400);
};

export const get_cookie_domain = () => {
  let explode = window.location.hostname.split(".");
  let cookie_domain =
    window.location.hostname === "localhost"
      ? window.location.hostname
      : explode.join(".");

  return cookie_domain;
};

